// NEW logic (transcribed exactly from TS)
const UNIT_TO_MILLIVOLTS = { uV: 1/1000, mV: 1, V: 1000 };
const SIGNAL_LEVELS = [ {at:0,label:"standby"},{at:50,label:"idle"},{at:200,label:"active"},{at:600,label:"loaded"},{at:900,label:"critical"} ];
const SEVERITY = { idle:1, active:2, loaded:3, critical:4, negative:5 };
const ALERT_LABELS = { loaded:true, critical:true, negative:true };
const MAX_READINGS = 500;
const normalizeValue=(u,v)=>Math.trunc(v*UNIT_TO_MILLIVOLTS[u]);
function classifySignal(mv){ if(mv<0)return "negative"; let l="standby"; for(const s of SIGNAL_LEVELS){ if(mv>=s.at) l=s.label;} return l; }
function severityRank(l){ return SEVERITY[l]??0; }
function collectAlerts(p){ const a=[]; for(const r of p){ const l=classifySignal(r.millivolts); if(ALERT_LABELS[l]) a.push(r.channel+":"+l);} return a; }
function processBatch(raw){
  const be=validateBatch(raw); if(be!==null) return {ok:false,error:be};
  const entries=raw.readings; const parsed=[];
  for(let i=0;i<entries.length;i++){ const o=parseReading(entries[i],i); if(typeof o==="string") return {ok:false,error:o}; parsed.push({channel:o.channel,millivolts:normalizeValue(o.unit,o.value),at:o.at}); }
  const labels=parsed.map(r=>classifySignal(r.millivolts));
  const alerts=collectAlerts(parsed);
  const channels=channelSummaries(parsed,labels);
  const report=buildReport(parsed.length,Object.keys(channels).length,alerts.length,labels);
  return {ok:true,readings:parsed.length,labels,channels,alerts,report};
}
function validateBatch(raw){ if(typeof raw!=="object"||raw===null)return "malformed batch"; if(!Array.isArray(raw.readings))return "missing readings"; if(raw.readings.length===0)return "empty batch"; if(raw.readings.length>MAX_READINGS)return "batch too large"; return null; }
function parseReading(e,i){ if(typeof e!=="object"||e===null)return "reading "+i+": malformed"; if(typeof e.channel!=="string"||e.channel.length===0)return "reading "+i+": bad channel"; if(UNIT_TO_MILLIVOLTS[e.unit]===undefined)return "reading "+i+": bad unit"; if(!Number.isInteger(e.value))return "reading "+i+": bad value"; if(!Number.isInteger(e.at)||e.at<0)return "reading "+i+": bad timestamp"; return {channel:e.channel,unit:e.unit,value:e.value,at:e.at}; }
function channelSummaries(p,labels){ const c={}; for(let i=0;i<p.length;i++){ const r=p[i]; const ex=c[r.channel]; if(ex===undefined){ c[r.channel]={count:1,min:r.millivolts,max:r.millivolts,worst:labels[i]}; continue; } ex.count++; if(r.millivolts<ex.min)ex.min=r.millivolts; if(r.millivolts>ex.max)ex.max=r.millivolts; if(severityRank(labels[i])>severityRank(ex.worst))ex.worst=labels[i]; } return c; }
function buildReport(rc,cc,ac,labels){ let w="standby"; for(const l of labels){ if(severityRank(l)>severityRank(w))w=l; } return "readings="+rc+";channels="+cc+";alerts="+ac+";worst="+w; }

// OLD logic
const UNITS=["uV","mV","V"];
const oldClassify=(mv)=>{ if(mv>=0&&mv<50)return"standby"; if(mv>=50&&mv<200)return"idle"; if(mv>=200&&mv<600)return"active"; if(mv>=600&&mv<900)return"loaded"; if(mv>=900)return"critical"; return"negative"; };
const oldRank=(l)=>{ if(l==="negative")return5; if(l==="critical")return4; if(l==="loaded")return3; if(l==="active")return2; if(l==="idle")return1; return0; };
const oldNorm=(u,v)=>{ if(u==="V")return v*1000; if(u==="uV")return Math.trunc(v/1000); return v; };
const oldAlerts=(p)=>{ const a=[]; for(const r of p){ if(r.millivolts>=900)a.push(r.channel+":critical"); else if(r.millivolts<0)a.push(r.channel+":negative"); else if(r.millivolts>=600&&r.millivolts<900)a.push(r.channel+":loaded"); } return a; };
function oldParse(e,i){ if(typeof e!=="object"||e===null)return "reading "+i+": malformed"; if(typeof e.channel!=="string"||e.channel.length===0)return "reading "+i+": bad channel"; if(UNITS.indexOf(e.unit)<0)return "reading "+i+": bad unit"; if(!Number.isInteger(e.value))return "reading "+i+": bad value"; if(!(Number.isInteger(e.at)&&e.at>=0))return "reading "+i+": bad timestamp"; return {channel:e.channel,unit:e.unit,value:e.value,at:e.at}; }
function oldProcessBatch(raw){ const be=oldValidate(raw); if(be!==null)return{ok:false,error:be}; const entries=raw.readings; const parsed=[]; for(let i=0;i<entries.length;i++){const o=oldParse(entries[i],i); if(typeof o==="string")return{ok:false,error:o}; parsed.push({channel:o.channel,millivolts:oldNorm(o.unit,o.value),at:o.at});} const labels=parsed.map(r=>oldClassify(r.millivolts)); const alerts=oldAlerts(parsed); const channels=oldSummaries(parsed,labels); const report=oldReport(parsed.length,Object.keys(channels).length,alerts.length,labels); return{ok:true,readings:parsed.length,labels,channels,alerts,report}; }
function oldValidate(raw){ if(typeof raw!=="object"||raw===null)return"malformed batch"; if(!Array.isArray(raw.readings))return"missing readings"; if(raw.readings.length===0)return"empty batch"; if(raw.readings.length>MAX_READINGS)return"batch too large"; return null; }
function oldSummaries(p,labels){ const c={}; for(let i=0;i<p.length;i++){const r=p[i]; const ex=c[r.channel]; if(ex===undefined){c[r.channel]={count:1,min:r.millivolts,max:r.millivolts,worst:labels[i]}; continue;} ex.count++; if(r.millivolts<ex.min)ex.min=r.millivolts; if(r.millivolts>ex.max)ex.max=r.millivolts; if(oldRank(labels[i])>oldRank(ex.worst))ex.worst=labels[i];} return c; }
