 {readings:[ {channel:"ch1",unit:"V",value:1,at:10}, {channel:"ch1",unit:"uV",value:250000,at:20}, {channel:"ch2",unit:"mV",value:-30,at:30}, {channel:"ch1",unit:"mV",value:700,at:40}, {channel:"ch2",unit:"mV",value:950,at:50} ]} ];
let fail=0;
for(const s of samples){ const a=processBatch(s), b=oldProcessBatch(s); if(JSON.stringify(a)!==JSON.stringify(b)){ fail++; console.log("MISMATCH batch",JSON.stringify(s)); console.log(" n",JSON.stringify(a)); console.log(" o",JSON.stringify(b)); } }
